class Info(ComponentCollection):
    r"""
    A base class to access various general information about the device and its driver.
    This class contains a collection of properties providing various information about
    the device and its driver.

    Instances of this class can't be constructed directly. Use one of the derived types.
    """

    thisown = property(lambda x: x.this.own(), lambda x, v: x.this.own(v), doc="The membership flag")
    __repr__ = _swig_repr

    def __init__(self, pDev):
        r"""
         Constructs a new **mvIMPACT::acquire::Info** object.
        :type pDev: :py:class:`Device`
        :param pDev: A pointer to a **mvIMPACT::acquire::Device** object obtained from a **mvIMPACT::acquire::DeviceManager** object.
        """
        lib_mvIMPACT_acquire.Info_swiginit(self, lib_mvIMPACT_acquire.new_Info(pDev))
    deviceDriverVersion = property(lib_mvIMPACT_acquire.Info_deviceDriverVersion_get, doc=r"""
    An integer property **(read-only)** containing the device driver version used by this device.
    This is the version of the underlying hardware driver. For device drivers that don't have another
    user mode driver below the interface driver this property will contain the same version information
    as the property **mvIMPACT::acquire::Info::driverVersion**.
    """)
    driverDate = property(lib_mvIMPACT_acquire.Info_driverDate_get, doc=r""" A string property **(read-only)** containing the date the device driver has been compiled.""")
    driverVersion = property(lib_mvIMPACT_acquire.Info_driverVersion_get, doc=r""" A string property **(read-only)** containing the version number of the device driver.""")
    state = property(lib_mvIMPACT_acquire.Info_state_get, doc=r"""
    An enumerated integer property **(read-only)** containing the current state of this device.
    This property e.g. provides information about the current state of the device. For USB devices this can e.g. indicate whether
    a device is currently plugged into the system or not.

    Valid values for this property are defined by the enumeration **mvIMPACT::acquire::TDeviceState**.

    **GenICam/GenTL** **device** **specific**:
    In order to reduce the amount of network traffic to a minimum, this property will only be updated automatically
    for network devices if the property **mvIMPACT::acquire::Device::registerErrorEvent** is set to
    **mvIMPACT::acquire::bTrue** (which is the default behaviour). If the IP addresses stay the same the
    connection is automatically re-established then once the device is detected by the driver again.
    However if the IP address of the device and/or the network adapter of the system it is used from changes
    **mvIMPACT::acquire::DeviceManager::updateDeviceList()**
    must be called regardless of the value of **mvIMPACT::acquire::Device::registerErrorEvent** before a device
    that was lost can re-establish a connection to the capture driver.
    """)
    loadedSettings = property(lib_mvIMPACT_acquire.Info_loadedSettings_get, doc=r""" A string property **(read-only)** containing the name of the setting currently loaded.""")
    logFile = property(lib_mvIMPACT_acquire.Info_logFile_get, doc=r""" A string property **(read-only)** containing the name and the full path of the current log-file for this device.""")
    systemPhysicalProcessorCount = property(lib_mvIMPACT_acquire.Info_systemPhysicalProcessorCount_get, doc=r"""
     An integer property **(read-only)** containing the number of physical processors detected in the current system.
    Since: 2.44.0
    """)
    systemLogicalProcessorCount = property(lib_mvIMPACT_acquire.Info_systemLogicalProcessorCount_get, doc=r"""
     An integer property **(read-only)** containing the number of logical processors detected in the current system.
    Since: 2.44.0
    """)
    captureBufferAlignment = property(lib_mvIMPACT_acquire.Info_captureBufferAlignment_get, doc=r""" An integer property **(read-only)** containing the capture buffer alignment in bytes needed by this device driver.""")
    recommendedListsForUIs = property(lib_mvIMPACT_acquire.Info_recommendedListsForUIs_get, doc=r""" A string property **(read-only)** containing an array of full search paths to lists which are recommended to be displayed in a user interface that is created dynamically.""")
    __swig_destroy__ = lib_mvIMPACT_acquire.delete_Info

# Register Info in lib_mvIMPACT_acquire:
lib_mvIMPACT_acquire.Info_swigregister(Info)

class BasicDeviceSettings(ComponentCollection):
    r"""
    A base class for essential device related settings.
    This class acts as a base class for essential device related settings. It only contains
    features that are available for every device.

    Since: 1.12.58
    """

    thisown = property(lambda x: x.this.own(), lambda x, v: x.this.own(v), doc="The membership flag")
    __repr__ = _swig_repr

    def __init__(self, *args):
        r"""
         brief Constructs a new **mvIMPACT::acquire::BasicDeviceSettings** object.
        :type pDev: :py:class:`Device`
        :param pDev: [in] A pointer to a **mvIMPACT::acquire::Device** object obtained from a **mvIMPACT::acquire::DeviceManager** object.
        :type settingName: string
        :param settingName: [in] The name of the driver internal setting to access with this instance. A list of valid setting names can be obtained by a call to **mvIMPACT::acquire::FunctionInterface::getAvailableSettings**, new settings can be created with the function **mvIMPACT::acquire::FunctionInterface::createSetting**
        """
