class ImageDisplayWindow(object):
    r"""
    A class that can be used to display images in a window.
    Every instance of this class will create and display its own independent window.
    Internally it uses an instance of **mvIMPACT::acquire::display::ImageDisplay**
    to display image data. The internal display object can be accessed by calling
    **mvIMPACT::acquire::display::ImageDisplayWindow::GetImageDisplay()**.
    """

    thisown = property(lambda x: x.this.own(), lambda x, v: x.this.own(v), doc="The membership flag")
    __repr__ = _swig_repr

    def __init__(self, title):
        r"""
         Creates a new window that can be used to display image data and displays it.
         This is an example of how to use the GetImageDisplay class.
         More details about this example.

        :type title: string
        :param title: [in] The title of the window (will be displayed in the windows title bar).
        """
        lib_mvIMPACT_acquire.ImageDisplayWindow_swiginit(self, lib_mvIMPACT_acquire.new_ImageDisplayWindow(title))
    __swig_destroy__ = lib_mvIMPACT_acquire.delete_ImageDisplayWindow

    def GetImageDisplay(self):
        r""" Returns a reference to the actual display object associated with this window."""
        return lib_mvIMPACT_acquire.ImageDisplayWindow_GetImageDisplay(self)

    def SetRefreshTime(self, time_ms):
        r"""
         Defines the refresh time in ms
         This function can be used to define a refresh period that - when elapsed -
         will automatically repaint the window.

        :type time_ms: int
        :param time_ms: [in] The refresh period for the window in ms. Passing *0* will disable the automatic repaint behaviour.
        """
        return lib_mvIMPACT_acquire.ImageDisplayWindow_SetRefreshTime(self, time_ms)

# Register ImageDisplayWindow in lib_mvIMPACT_acquire:
lib_mvIMPACT_acquire.ImageDisplayWindow_swigregister(ImageDisplayWindow)



